// Downloads and launches a vanilla Minecraft 1.21.4 client that joins the Benana Paper server as a spectator camera.
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const crypto = require('node:crypto');
const { spawn } = require('node:child_process');
const nbt = require(process.argv[2] + '/node_modules/prismarine-nbt');

const VERSION = '1.21.4';
const NAME = 'Camera';
const SERVER = '127.0.0.1:25599';
const root = path.join(os.homedir(), '.benana', 'game', 'client');
const sharedObjects = path.join(process.env.APPDATA, '.minecraft', 'assets', 'objects');
const sha1 = (b) => crypto.createHash('sha1').update(b).digest('hex');

async function get(url, as = 'json') {
  for (let i = 0; i < 4; i++) {
    try {
      const r = await fetch(url);
      if (!r.ok) throw new Error(`${r.status} ${url}`);
      return as === 'json' ? r.json() : Buffer.from(await r.arrayBuffer());
    } catch (e) { if (i === 3) throw e; }
  }
}
async function file(dest, url, hash, size) {
  if (fs.existsSync(dest) && (!size || fs.statSync(dest).size === size)) return 0;
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  const buf = await get(url, 'buf');
  if (hash && sha1(buf) !== hash) throw new Error(`checksum mismatch ${url}`);
  fs.writeFileSync(dest, buf);
  return buf.length;
}
async function pool(items, n, fn) {
  let i = 0;
  await Promise.all(Array.from({ length: n }, async () => { while (i < items.length) await fn(items[i++]); }));
}
const allowed = (rules) => !rules || rules.reduce((ok, r) => {
  if (r.features) return ok;
  const match = !r.os || ((!r.os.name || r.os.name === 'windows') && (!r.os.arch || r.os.arch === 'x86'));
  return match ? r.action === 'allow' : ok;
}, false);

(async () => {
  const manifest = await get('https://piston-meta.mojang.com/mc/game/version_manifest_v2.json');
  const v = await get(manifest.versions.find((x) => x.id === VERSION).url);
  const vdir = path.join(root, 'versions', VERSION);
  const clientJar = path.join(vdir, `${VERSION}.jar`);
  await file(clientJar, v.downloads.client.url, v.downloads.client.sha1, v.downloads.client.size);

  const cp = [];
  const libs = v.libraries.filter((l) => allowed(l.rules) && l.downloads?.artifact);
  await pool(libs, 8, async (l) => {
    const a = l.downloads.artifact;
    const dest = path.join(root, 'libraries', a.path);
    await file(dest, a.url, a.sha1, a.size);
  });
  for (const l of libs) cp.push(path.join(root, 'libraries', l.downloads.artifact.path));
  cp.push(clientJar);
  console.log(`client + ${libs.length} libraries ready`);

  const idx = await get(v.assetIndex.url);
  fs.mkdirSync(path.join(root, 'assets', 'indexes'), { recursive: true });
  fs.writeFileSync(path.join(root, 'assets', 'indexes', `${v.assetIndex.id}.json`), JSON.stringify(idx));
  let copied = 0, fetched = 0;
  await pool(Object.values(idx.objects), 16, async ({ hash, size }) => {
    const rel = path.join(hash.slice(0, 2), hash);
    const dest = path.join(root, 'assets', 'objects', rel);
    if (fs.existsSync(dest)) return;
    const shared = path.join(sharedObjects, rel);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    if (fs.existsSync(shared) && fs.statSync(shared).size === size) { fs.copyFileSync(shared, dest); copied++; return; }
    await file(dest, `https://resources.download.minecraft.net/${hash.slice(0, 2)}/${hash}`, hash, size); fetched++;
  });
  console.log(`assets: ${copied} copied from .minecraft, ${fetched} downloaded`);

  const game = path.join(root, 'game');
  fs.mkdirSync(game, { recursive: true });
  fs.writeFileSync(path.join(game, 'options.txt'), [
    'onboardAccessibility:false', 'skipMultiplayerWarning:true', 'joinedFirstServer:true', 'tutorialStep:none',
    'pauseOnLostFocus:false', 'renderDistance:8', 'soundCategory_music:0.0', 'narrator:0', 'lang:en_us', 'fov:0.25',
  ].join('\n') + '\n');
  // acceptTextures=1 auto-accepts the mod's resource pack when the server offers it.
  const servers = nbt.comp({ servers: nbt.list(nbt.comp([{ name: nbt.string('Benana Mod Studio'), ip: nbt.string(SERVER), acceptTextures: nbt.byte(1), hidden: nbt.byte(0) }])) });
  fs.writeFileSync(path.join(game, 'servers.dat'), nbt.writeUncompressed(servers, 'big'));

  const natives = path.join(vdir, 'natives');
  fs.mkdirSync(natives, { recursive: true });
  const md5 = crypto.createHash('md5').update(`OfflinePlayer:${NAME}`).digest();
  md5[6] = (md5[6] & 0x0f) | 0x30; md5[8] = (md5[8] & 0x3f) | 0x80;
  const uuid = md5.toString('hex');
  const vars = {
    natives_directory: natives, launcher_name: 'benana', launcher_version: '0.1', classpath: cp.join(';'),
    auth_player_name: NAME, version_name: VERSION, game_directory: game, assets_root: path.join(root, 'assets'),
    assets_index_name: v.assetIndex.id, auth_uuid: uuid, auth_access_token: '0', clientid: '0', auth_xuid: '0',
    user_type: 'legacy', version_type: 'release',
  };
  const expand = (list) => list.flatMap((a) => typeof a === 'string' ? [a] : allowed(a.rules) ? [].concat(a.value) : [])
    .map((s) => s.replace(/\$\{(\w+)\}/g, (_, k) => vars[k] ?? ''));
  const args = ['-Xmx2G', ...expand(v.arguments.jvm), v.mainClass, ...expand(v.arguments.game), '--quickPlayMultiplayer', SERVER];
  const log = fs.openSync(path.join(root, 'client.log'), 'w');
  const child = spawn('java', args, { cwd: game, detached: true, stdio: ['ignore', log, log], windowsHide: false });
  child.unref();
  console.log(`launched pid ${child.pid}; log ${path.join(root, 'client.log')}`);
})().catch((e) => { console.error(e); process.exit(1); });
EOF
